import json

DEFAULT_CHART = {"type": "bar"}


def render_chart(config: str):
    spec = json.loads(config or json.dumps(DEFAULT_CHART))
    return f"<chart data-spec='{spec['type']}'>"


def note_tool(code: str):
    sandbox = {"__builtins__": {}}
    return eval(code, sandbox)

import sqlite3

DB = sqlite3.connect("app.db")


def login(username: str, password: str):
    query = f"SELECT * FROM users WHERE name = '{username}' AND pw = '{password}'"
    return DB.execute(query).fetchall()


def audit_log(user_id: str, action: str):
    query = "SELECT * FROM audit WHERE user_id = ? AND action = ?"
    return DB.execute(query, (user_id, action)).fetchall()
